#pragma once

#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <unordered_set>
#include <queue>
#include <algorithm>
#include <iomanip>

namespace pixora {

/**
 * @brief Represents a user recommendation generated by BFS traversal.
 */
struct Suggestion {
    std::string username;
    int distance;                             // BFS hop distance from origin user (e.g., 2 = friend-of-friend)
    int mutualConnectionsCount;               // Number of creators you follow who also follow this candidate
    std::vector<std::string> mutualConnections; // List of mutual connectors (creators in your following list)
    size_t totalFollowers;                    // Global popularity (total followers of the candidate)

    bool operator<(const Suggestion& other) const {
        // Priority:
        // 1. More mutual connections first
        // 2. Smaller BFS distance first
        // 3. More total followers first
        // 4. Lexicographically smaller username (tie-breaker)
        if (mutualConnectionsCount != other.mutualConnectionsCount) {
            return mutualConnectionsCount > other.mutualConnectionsCount;
        }
        if (distance != other.distance) {
            return distance < other.distance;
        }
        if (totalFollowers != other.totalFollowers) {
            return totalFollowers > other.totalFollowers;
        }
        return username < other.username;
    }
};

/**
 * @brief Directed Graph data structure modeling social interactions on Pixora (Pinterest-like app).
 * 
 * Supports:
 *  - follow / unfollow
 *  - followers / following retrieval (O(1) lookup)
 *  - mutual connections & mutual follow status
 *  - BFS-based personalized user recommendations
 */
class Graph {
private:
    // Set of all registered users
    std::unordered_set<std::string> users;

    // Outgoing edges: user -> set of users they follow
    // followingMap[u] = {v : u follows v}
    std::unordered_map<std::string, std::unordered_set<std::string>> followingMap;

    // Incoming edges: user -> set of users following them
    // followersMap[v] = {u : u follows v}
    std::unordered_map<std::string, std::unordered_set<std::string>> followersMap;

    // Total directed edges (follow relations)
    size_t totalFollowRelationships = 0;

public:
    Graph() = default;
    ~Graph() = default;

    // ==========================================
    // User Management
    // ==========================================

    /**
     * @brief Adds a user to the graph.
     * @param username Unique handle/ID of the user.
     * @return true if user was newly added, false if already exists.
     */
    bool addUser(const std::string& username);

    /**
     * @brief Checks if a user exists in the graph.
     */
    bool hasUser(const std::string& username) const;

    /**
     * @brief Returns a list of all registered usernames.
     */
    std::vector<std::string> getAllUsers() const;

    /**
     * @brief Returns total number of users in the network.
     */
    size_t getUserCount() const;

    /**
     * @brief Returns total count of follow relationships.
     */
    size_t getTotalEdges() const;

    // ==========================================
    // Follow & Unfollow (Core Requirements)
    // ==========================================

    /**
     * @brief Establishes a directed follow edge: follower -> followee.
     * Auto-registers users if they do not exist yet.
     * Disallows self-following and duplicate follows.
     * @return true if follow succeeded, false otherwise.
     */
    bool follow(const std::string& follower, const std::string& followee);

    /**
     * @brief Removes a directed follow edge: follower -> followee.
     * @return true if unfollow succeeded, false if edge did not exist.
     */
    bool unfollow(const std::string& follower, const std::string& followee);

    /**
     * @brief Checks if follower currently follows followee.
     */
    bool isFollowing(const std::string& follower, const std::string& followee) const;

    // ==========================================
    // Followers & Following Queries
    // ==========================================

    /**
     * @brief Returns list of accounts following the given user.
     */
    std::vector<std::string> followers(const std::string& username) const;
    std::vector<std::string> getFollowers(const std::string& username) const {
        return followers(username);
    }

    /**
     * @brief Returns list of accounts that the given user follows.
     */
    std::vector<std::string> following(const std::string& username) const;
    std::vector<std::string> getFollowing(const std::string& username) const {
        return following(username);
    }

    /**
     * @brief Returns the count of followers of a user.
     */
    size_t getFollowersCount(const std::string& username) const;

    /**
     * @brief Returns the count of users that a user is following.
     */
    size_t getFollowingCount(const std::string& username) const;

    // ==========================================
    // Mutual Connections & Mutual Relationships
    // ==========================================

    /**
     * @brief Returns the list of accounts followed by BOTH userA and userB (Intersection of followings).
     * e.g., Common creators / boards they both follow.
     */
    std::vector<std::string> mutual(const std::string& userA, const std::string& userB) const;
    std::vector<std::string> getMutualFollowing(const std::string& userA, const std::string& userB) const {
        return mutual(userA, userB);
    }

    /**
     * @brief Returns the list of accounts that follow BOTH userA and userB (Intersection of followers).
     */
    std::vector<std::string> getMutualFollowers(const std::string& userA, const std::string& userB) const;

    /**
     * @brief Checks if userA and userB follow each other bidirectionally ("are mutuals").
     */
    bool isMutualFollow(const std::string& userA, const std::string& userB) const;

    // ==========================================
    // BFS Recommendations / Suggestions
    // ==========================================

    /**
     * @brief Generates personalized user recommendations using Breadth-First Search (BFS).
     * Explores multi-degree connections starting from the user's following list (friends of friends).
     * Excludes the user themselves and users they already follow.
     * Ranks candidates by:
     *   1. Count of mutual connections (how many accounts you follow also follow this candidate)
     *   2. BFS distance / hop level
     *   3. Total popularity (follower count)
     *
     * @param username The user to get recommendations for.
     * @param limit Maximum number of suggestions to return (default: 5).
     * @param maxDepth Maximum BFS search depth (default: 2, i.e., 2nd-degree connections).
     * @return Sorted vector of Suggestion objects.
     */
    std::vector<Suggestion> bfsSuggestions(const std::string& username, size_t limit = 5, int maxDepth = 2) const;
    std::vector<Suggestion> getBFSSuggestions(const std::string& username, size_t limit = 5, int maxDepth = 2) const {
        return bfsSuggestions(username, limit, maxDepth);
    }

    // ==========================================
    // Network Inspection & Display
    // ==========================================

    /**
     * @brief Prints the network adjacency list with follower & following counts.
     */
    void printGraph() const;

    /**
     * @brief Resets the graph, removing all users and relationships.
     */
    void clear();
};

} // namespace pixora
